import os
import torch


class Config:
    # =========================================================================
    # Paths & Directories
    # =========================================================================
    # Root directories
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working"

    # Specific output directory for this idea (Idea 10)
    OUTPUT_DIR = os.path.join(WORKING_DIR, "idea_10")

    # Metadata file paths (generated by the provided script)
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")
    SUBMISSION_CSV = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Data directories (read-only input)
    # Note: The metadata dataframe contains relative paths (e.g., "train_eegs/123.parquet")
    # so we often join INPUT_DIR with those relative paths.
    TRAIN_EEGS_DIR = os.path.join(INPUT_DIR, "train_eegs")
    TRAIN_SPECTROGRAMS_DIR = os.path.join(INPUT_DIR, "train_spectrograms")
    TEST_EEGS_DIR = os.path.join(INPUT_DIR, "test_eegs")
    TEST_SPECTROGRAMS_DIR = os.path.join(INPUT_DIR, "test_spectrograms")

    # =========================================================================
    # Global Settings
    # =========================================================================
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 8  # Optimized for the 12 vCPU environment
    PIN_MEMORY = True

    # =========================================================================
    # Data Processing Parameters
    # =========================================================================
    # --- EEG Stream ---
    EEG_ORIGINAL_RATE = 200
    EEG_TARGET_RATE = 100  # Downsampling to 100 Hz as per strategy
    EEG_DURATION_SEC = 50
    EEG_SEQ_LEN = EEG_TARGET_RATE * EEG_DURATION_SEC  # 5000 time steps
    EEG_CHANNELS = 20  # 19 EEG + 1 EKG

    # --- Spectrogram Stream ---
    # Original spectrograms cover 10 minutes (600 seconds)
    SPEC_DURATION_SEC = 600
    # Input image size for the EfficientNet backbone (Height, Width)
    # EDA showed avg width ~400 (freq), height varies (time).
    # We resize to a fixed square for the CNN.
    IMG_SIZE = (512, 512)

    # Channels: 4 original (LL, RL, LP, RP) + 1 Coordinate Channel
    SPEC_USE_CHANNELS = ["LL", "RL", "LP", "RP"]
    N_SPEC_CHANNELS = 4
    N_COORD_CHANNELS = 1
    TOTAL_INPUT_CHANNELS = N_SPEC_CHANNELS + N_COORD_CHANNELS  # 5 channels

    # Coordinate Injection Settings
    # Range to normalize the relative time coordinates to (e.g., -1 to 1)
    COORD_RANGE = (-1.0, 1.0)

    # =========================================================================
    # Model Architecture Parameters
    # =========================================================================
    # Spectrogram Encoder
    BACKBONE = "efficientnet_b0"
    PRETRAINED = True

    # EEG Encoder (1D CNN)
    EEG_KERNEL_SIZES = [3, 5, 7]
    EEG_FILTERS = [64, 128, 256]

    # Fusion & Head
    FUSION_DIM = 128  # Dimension to project both streams to before fusion/concat
    NUM_CLASSES = 6
    DROPOUT_RATE = 0.2

    # =========================================================================
    # Training Hyperparameters
    # =========================================================================
    BATCH_SIZE = 32  # Safe for A100 40GB with this dual-stream model
    EPOCHS = 6  # Training for limited epochs as per instructions

    # Optimizer & Scheduler
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 0.01
    MAX_LR = 1e-3
    PCT_START = 0.3  # For OneCycleLR
    DIV_FACTOR = 25
    FINAL_DIV_FACTOR = 1000

    # Early Stopping
    PATIENCE = 3

    # Loss
    # Using KL Divergence for soft probability targets
    LOSS_FUNC = "KLDivLoss"

    # =========================================================================
    # Caching / Debugging
    # =========================================================================
    # If True, processes data once and saves .npy/.parquet files to OUTPUT_DIR
    USE_CACHE = True
    # If > 0, only uses a subset of data for quick debugging
    DEBUG_SAMPLE_SIZE = 0

    @classmethod
    def get_output_dir(cls):
        """Ensures output directory exists and returns it."""
        os.makedirs(cls.OUTPUT_DIR, exist_ok=True)
        return cls.OUTPUT_DIR
